head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.pageSize = 10; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vPAGENO = 0;
scwin.vScrenID = "ULDSTF34001.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    // 한달전 날짜 
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    $c.stf.setObjectValue(edt_SDATE, $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    $c.stf.setObjectValue(edt_EDATE, $c.ut.cGetToday2());
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    if (js_market != "9") {
        $c.stf.showObj(panel_mkt, false);
    }
};
scwin.fn_listRoadZipCdAppl = function() {
    var argv = fn_listRoadZipCdAppl.arguments;
    var argc = fn_listRoadZipCdAppl.arguments.length;
    scwin.vPAGENO = (argc == 0) ? 0 : scwin.vPAGENO = argv[0];
    $c.cm.ShowWin(grd_Grid);
    var url = "/ListedCompanyPassword.do?method=listRoadZipcdAppl";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&COM_NM=" + $c.stf.getObjectValue(txb_COM_NM);
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&APPL_RSLT=" + $c.stf.getObjectValue(cmb_APPL_RSLT);
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&EMP_NO=" + scwin.gEmpNo;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (scwin.gLdMktTp == "1") {
        url += "&CORP_USR_TP_CD=11";
    } else if (scwin.gLdMktTp == "2") {
        url += "&CORP_USR_TP_CD=21";
    } else if (scwin.gLdMktTp == "4") {
        url += "&CORP_USR_TP_CD=19";
    } else if (scwin.gLdMktTp == "6") {
        url += "&CORP_USR_TP_CD=61";
    } else {
        url += "&CORP_USR_TP_CD=" + $c.stf.getObjectValue(cmb_CORP_USR_TP_CD);
    }
    url += "&PAGENO=" + scwin.vPAGENO;
    url += "&PAGESIZE=" + $c.stf.getObjectValue(cmb_PerPage);
    dts_RoadZipCdApplList.DataID = encodeURI(url);
    dts_RoadZipCdApplList.Reset();
};
scwin.PageNoCall = function(vPageNo) {
    scwin.vCurrPageNo = vPageNo;
    scwin.fn_listRoadZipCdAppl(vPageNo);
};
scwin.fn_SetCode = function() {
    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
    $c.stf.Combo_CBDataSet(cmb_PerPage);
    $c.stf.setObjectValue(cmb_APPL_RSLT, "R");
    dts_CORP_USR_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=CORP_USR_TP_CD";
    dts_CORP_USR_TP_CD.Reset();

    // 채권상장팀의 경우 팀선택 및 팀원선택박스 '전체' 로 디폴트 갖도록 변경.  20130912 by LDJ(송은진과장님 요청사항)
    if (js_bond_yn == "Y") {
        scwin.gDepCd = '';
        scwin.gEmpNo = '';
    }
};
scwin.fn_readRoadZipCdAppl = async function(row, colid) {
    if (colid == "CHG_PROCS_STAT_CD_NM") {
        // 처리현황 클릭 시
        gISUR_CD = dts_RoadZipCdApplList.getCellData(eval(row), "ISUR_CD");
        gLD_MKT_TP_CD = dts_RoadZipCdApplList.getCellData(eval(row), "LD_MKT_TP_CD");
        gCORP_USR_TP_CD = dts_RoadZipCdApplList.getCellData(eval(row), "CORP_USR_TP_CD");
        gADDR_CHG_TP_CD = dts_RoadZipCdApplList.getCellData(eval(row), "ADDR_CHG_TP_CD");
        gSEQ = dts_RoadZipCdApplList.getCellData(eval(row), "SEQ");
        gCOM_ABBRV = dts_RoadZipCdApplList.getCellData(eval(row), "COM_ABBRV");
        gCORP_USR_TP_CD_NM = dts_RoadZipCdApplList.getCellData(eval(row), "CORP_USR_TP_CD_NM");
        gAPPL_DDTM = dts_RoadZipCdApplList.getCellData(eval(row), "APPL_DDTM");
        gBFCHG_ZIPCD = dts_RoadZipCdApplList.getCellData(eval(row), "BFCHG_ZIPCD");
        gBF_ADDR = dts_RoadZipCdApplList.getCellData(eval(row), "BF_ADDR");
        gAFCHG_ZIPCD = dts_RoadZipCdApplList.getCellData(eval(row), "AFCHG_ZIPCD");
        gAF_ADDR = dts_RoadZipCdApplList.getCellData(eval(row), "AF_ADDR");
        gCHG_PROCS_STAT_CD = dts_RoadZipCdApplList.getCellData(eval(row), "CHG_PROCS_STAT_CD");
        var url = "/issueinfo/ULDSTF34002.gfm";
        var winTitle = "상장법인 본점소재지 도로명주소 변경신청 처리";
        await $c.frame.CreateDialogFrame("ULDSTF37407", url, winTitle, 100, 100, 730, 350, "window");
    } else if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_RoadZipCdApplList.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "ATTACH_FILE_NM") {
        seq = dts_RoadZipCdApplList.getCellData(row, "SEQ");
        //alert(seq);
        scwin.fn_filedown(seq);
    }
};






//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?attach_seq=" + attach_seq + "&gubun=29";
};
scwin.btn_Search_onclick = function() {
    scwin.fn_listRoadZipCdAppl();
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "본점소재지 도로명주소 변경신청 목록", "", "8");
};
scwin.cmb_PerPage_OnSelChange = function() {
    scwin.vCurrPageNo = 1;
};
scwin.dts_RoadZipCdApplList_OnLoadCompleted = function(rowcount) {
    if (scwin.vPAGENO == 0) {
        scwin.vCurrPageNo = 1;
    }
    var vTotalCnt = dts_RoadZipCdApplList.getCellData(1, "CNT");
    $c.stf.FillGridHeader2(scwin.pageNoCnt, $c.stf.getObjectValue(cmb_PerPage), vTotalCnt, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_RoadZipCdApplList_OnLoadError = function() {
    $c.stf.alert_error(dts_RoadZipCdApplList);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_readRoadZipCdAppl(row, colid);
};
scwin.btn_ISUR_CD_onclick = function() {
    //2009.09.01 채권공시관련 - 채권법인검색창
    if (js_bond_yn == "Y") {
        $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM);
    } else {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_TeamList, scwin.gDepCd);
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_EmpList, scwin.gEmpNo);
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.cmb_EmpList_OnSelChange = function() {
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_Init();
    if (scwin.gLdMktTp != "9") {
        label_3.style.display = "none";
        cmb_CORP_USR_TP_CD.style.display = "none";
    }
    scwin.fn_listRoadZipCdAppl();
};
